#!/usr/bin/env python3
"""Build a local rehearsal page for the strongest recurring three-move triads."""

from __future__ import annotations

import html
import json
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SOURCE = ROOT / "research/compound-pattern-triads.json"
OUT = ROOT / "writeups/compound-pattern-triads.html"


def build() -> str:
    triads = json.loads(SOURCE.read_text())["triads"]
    data = json.dumps(triads, ensure_ascii=False, separators=(",", ":"))
    cards = "".join(f'<article class="card" data-search="{html.escape((item["triad_id"]+" "+item["candidate_form"]).lower())}"><h2>{html.escape(item["triad_id"])}</h2><p class=form>{html.escape(item["candidate_form"])}</p><p>Co-occurrence: {item["cooccurrence_review_count"]} reviews</p><p>{html.escape(item["practice_prompt"])}</p><p class=boundary>{html.escape(item["non_fit_warning"])}</p><details><summary>Source excerpts</summary>{''.join(f'<blockquote>Move {i+1}: {html.escape(excerpt)}</blockquote>' for example in item["examples"][:2] for i, excerpt in enumerate(example["excerpts"]) if excerpt)}</details></article>' for item in triads)
    options = "".join(f'<option value="{html.escape(item["triad_id"])}">{html.escape(item["triad_id"])} ({item["cooccurrence_review_count"]} reviews)</option>' for item in triads)
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Three-move speech-pattern practice</title><style>:root{{--bg:#f6f7fb;--fg:#172033;--muted:#5b6475;--card:#fff;--line:#d9deea;--accent:#2457d6;--warn:#fff3d6}}body{{margin:0;background:var(--bg);color:var(--fg);font:16px/1.55 system-ui,sans-serif}}main{{max-width:1100px;margin:auto;padding:28px 18px 70px}}.builder,.card{{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:18px;margin:16px 0}}.fields{{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px}}label{{display:flex;flex-direction:column;gap:4px;font-weight:600}}input,textarea,select{{box-sizing:border-box;padding:10px;border:1px solid var(--line);border-radius:8px;font:inherit;background:var(--card);color:var(--fg)}}textarea{{width:100%;min-height:220px}}button{{padding:10px 14px;border:0;border-radius:8px;background:var(--accent);color:#fff;font:inherit;cursor:pointer;margin:6px 6px 6px 0}}.form{{color:var(--accent)}}.boundary{{background:var(--warn);padding:10px;border-radius:6px}}.muted{{color:var(--muted)}}a{{color:var(--accent)}}</style></head><body><main><h1>Three-move speech-pattern practice</h1><p class=muted>These are corpus-mined triads that co-occurred in at least three reviews. Co-occurrence is not proof of order or effectiveness.</p><section class=builder><div class=fields><label>Topic<input id=topic></label><label>Audience<input id=audience></label><label>Triad<select id=triad><option value="">Choose a triad…</option>{options}</select></label></div><p id=info></p><textarea id=draft placeholder="Choose a triad and generate a three-move scaffold."></textarea><div class=fields><label>Listener restatement<textarea id=listener></textarea></label><label>Still unclear<textarea id=unclear></textarea></label><label>Non-fit<textarea id=nonfit></textarea></label><label>Next revision<textarea id=revision></textarea></label></div><button id=generate>Generate scaffold</button><button id=save>Save locally</button><button id=load>Load saved</button><button id=download>Download JSON</button><span id=status></span></section><input id=search placeholder="Find a triad"><section id=cards>{cards}</section><script>const triads={data},byId=Object.fromEntries(triads.map(x=>[x.triad_id,x])),select=document.getElementById('triad'),draft=document.getElementById('draft'),reflection=['listener','unclear','nonfit','revision'];function show(){{const x=byId[select.value];document.getElementById('info').textContent=x?'Candidate form: '+x.candidate_form:''}}select.onchange=show;generate.onclick=()=>{{const x=byId[select.value];if(!x){{status.textContent='Choose a triad first.';return}}draft.value='# Three-move presentation: '+(topic.value||'[topic]')+'\\n\\nAudience: '+(audience.value||'[audience]')+'\\n\\nMove 1: '+x.pattern_names[0]+'\\nWrite the first move.\\n\\nBridge: explain why the second move follows.\\n\\nMove 2: '+x.pattern_names[1]+'\\nWrite the second move.\\n\\nBridge: explain why the third move follows.\\n\\nMove 3: '+x.pattern_names[2]+'\\nWrite the third move with its condition or limit.\\n\\nSelf-check: '+x.self_check+'\\nBoundary: '+x.non_fit_warning}};save.onclick=()=>{{localStorage.setItem('triad-draft',JSON.stringify({{topic:topic.value,audience:audience.value,triad_id:select.value,draft:draft.value,reflections:Object.fromEntries(reflection.map(id=>[id,document.getElementById(id).value]))}}));status.textContent='Saved on this device.'}};load.onclick=()=>{{const x=JSON.parse(localStorage.getItem('triad-draft')||'null');if(!x){{status.textContent='No saved draft.';return}}topic.value=x.topic||'';audience.value=x.audience||'';select.value=x.triad_id||'';draft.value=x.draft||'';reflection.forEach(id=>document.getElementById(id).value=(x.reflections||{{}})[id]||'');show();status.textContent='Loaded from this device.'}};download.onclick=()=>{{const x=byId[select.value],record={{record_type:'local_compound_triad_practice_record',schema_version:'1.0',triad_id:select.value,source_review_ids:x?x.examples.map(e=>e.review_id):[],source_evidence_ids:x?x.examples.flatMap(e=>e.evidence_ids.flat()):[],draft:draft.value,reflections:Object.fromEntries(reflection.map(id=>[id,document.getElementById(id).value])),claim_boundary:'Local triad candidate practice record; not recurrence proof, learner evidence, listener outcomes, causal evidence, or effectiveness evidence.',saved_at:new Date().toISOString()}};const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(record,null,2)],{{type:'application/json'}}));a.download='compound-triad-practice.json';a.click()}};search.oninput=()=>{{const q=search.value.toLowerCase();document.querySelectorAll('.card').forEach(c=>c.hidden=q&&!c.dataset.search.includes(q))}};</script></main></body></html>'''


if __name__ == "__main__":
    OUT.write_text(build().replace("status.textContent", "document.getElementById('status').textContent"))
    print(f"compound triad browser: {len(json.loads(SOURCE.read_text())['triads'])} triads")
